"use client";
// @zeus-internal
import { useMotionTemplate, useSpring } from "motion/react";
import type { PointerEvent } from "react";

/** A surface-relative light that follows the pointer without layout reads per frame. */
export function useArtemisSpotlight(reduced: boolean) {
  const horizontal = useSpring(50, { stiffness: 180, damping: 24 });
  const vertical = useSpring(50, { stiffness: 180, damping: 24 });
  const mask = useMotionTemplate`radial-gradient(circle 180px at ${horizontal}% ${vertical}%, black 0%, black 35%, transparent 76%)`;
  function onPointerMove({ currentTarget, clientX, clientY }: PointerEvent<HTMLElement>) {
    if (reduced) return;
    const bounds = currentTarget.getBoundingClientRect();
    if (bounds.width <= 0 || bounds.height <= 0) return;
    horizontal.set(100 * (clientX - bounds.x) / bounds.width);
    vertical.set(100 * (clientY - bounds.y) / bounds.height);
  }
  return { mask, onPointerMove };
}
